 const matches=periods.some(period=>{const open=period?.open,close=period?.close;if(!open)return false;const od=Number(open.day),om=Number(open.hour||0)*60+Number(open.minute||0);if(!close)return od===day&&minutes>=om;const cd=Number(close.day),cm=Number(close.hour||0)*60+Number(close.minute||0);if(od===cd)return od===day&&minutes>=om&&minutes<cm;if(day===od)return minutes>=om;if(day===cd)return minutes<cm;return od<cd?day>od&&day<cd:day>od||day<cd});
