function calculateMatchScore(place){let score=58+(window.LuviaTravelPreferences?.score?.(place,'restaurants')||0);const rating=Number(place?.rating)||0,reviews=Number(place?.userRatingCount)||0,distance=Number(place?.distanceMeters);score+=Math.max(0,(rating-3.5)*14);score+=Math.min(10,Math.log10(Math.max(1,reviews))*3);if(place?.features?.servesVegetarianFood===true)score+=7;if(place?.features?.reservable===true)score+=4;if(Number.isFinite(distance))score+=distance<1500?8:distance<5000?5:distance<12000?2:-3;return Math.max(55,Math.min(98,Math.round(score)))}
function normalizeMatchScore(place){if(!place||typeof place!=='object')return place;const provided=Number(place.matchScore),calculated=calculateMatchScore(place);const resolved=Number.isFinite(provided)&&provided>55?Math.round(provided):calculated;return {...place,matchScore:Math.max(55,Math.min(98,resolved))}}
