function participantMatches(place){const intel=restaurantIntel(place),rows=intel.participantMatches||[],group=intel.groupInsight||{};if(!rows.length)return '<p class="rv2-muted">Noch kein Teilnehmerprofil ist vollständig auswertbar.</p>';return `<div class="rv2-participant-matches">${rows.map(row=>`<div><span>${esc(row.name||'Reisemitglied')}</span><strong>${esc(row.score)} %</strong><progress class="rv2-match-progress" max="100" value="${Math.max(0,Math.min(100,Number(row.score)||0))}" aria-label="${esc(row.score)} Prozent Übereinstimmung"></progress></div>`).join('')}</div>${group.known>group.evaluated?`<p class="rv2-group-note">${esc(group.known-group.evaluated)} weitere${group.known-group.evaluated===1?'s':''} Profil${group.known-group.evaluated===1?'':'e'} fließen ein, sobald dort Präferenzen hinterlegt sind.</p>`:''}`}
