function card(e,ctx,settings){const menu=e.menu||{},map=validCustomMaps(e.mapsUrl)||generatedMapsUrl(e,ctx),distance=entryDistance(e),intel=restaurantIntel(e),place={...e,primaryType:'restaurant',roles:e.roles||[],lifecycle:e.isFavorite?'favorite':(e.lifecycleStatus||'discovered'),address:e.address,description:e.description};if(window.LuviaPlaceUI)return window.LuviaPlaceUI.card(place,{className:'rv2-card rv2-card-intelligent',openAttribute:`data-rv2-open-workspace="${esc(e.id)}"`,intelligence:{...intel,distanceLabel:distance||intel.distanceLabel},extra:`${settings.showCountdown!==false&&e.date?`<div class="rv2-countdown" data-rv2-countdown="${esc(e.id)}">${esc(countdown(e))}</div>`:''}${lifecycleTimeline(e.isFavorite?'favorite':normalizeCoreLifecycle(e.lifecycleStatus||'discovered'))}`,actions:`<button class="rv2-action primary" type="button" data-rv2-workspace="${esc(e.id)}">✨ Ort öffnen</button>${menu.enabled&&(menu.assetId||menu.original||(menu.pages||[]).length)?`<button class="rv2-action" type="button" data-rv2-menu="${esc(e.id)}">📖 ${esc(menu.label||'Speisekarte')}</button>`:''}${map?`<a class="rv2-action secondary" href="${esc(map)}" target="_blank" rel="noopener">Maps öffnen ↗</a>`:''}`});return `<article class="rv2-card"><h3>${esc(e.name)}</h3></article>`}
function searchResultCard(place,added){const intel=restaurantIntel(place),distance=intel.distanceLabel||formatDistance(place.distanceMeters),rating=place.rating?`${Number(place.rating).toFixed(1).replace('.',',')} ★`:'Neu',universal={...place,primaryType:'restaurant',roles:place.roles||[],lifecycle:added?'favorite':'discovered',address:place.shortAddress||place.formattedAddress,description:`${rating} · ${place.userRatingCount||0} Bewertungen${distance?' · '+distance:''}`};if(window.LuviaPlaceUI)return window.LuviaPlaceUI.card(universal,{className:'rv2-search-card rv2-search-card-intelligent',openAttribute:`data-rv2-details="${esc(place.id)}"`,media:place._cardPhotoUri?`<div class="rv2-card-media"><img src="${esc(place._cardPhotoUri)}" alt="${esc(place.name)}" loading="eager" fetchpriority="high" decoding="sync"></div>`:`<div class="rv2-card-media is-placeholder"><span>🍽️</span></div>`,intelligence:intel,actions:`<button type="button" class="rv2-detail-button primary" data-rv2-details="${esc(place.id)}">Warum passt das?</button><button type="button" data-rv2-import="${esc(place.id)}" ${added?'disabled':''}>${added?'Favorit ✓':'♡ Favorit'}</button>`});return `<article class="rv2-search-card"><strong>${esc(place.name)}</strong></article>`}
