function ensureRestaurantInteractivity(instance){
  if(!instance)return;
  const shellRoot=document.querySelector('.luvia-app-screen[data-screen="restaurants"] #restaurants-module');
  const current=shellRoot||document.querySelector('#restaurants-module');
  if(!current)return;
  const bound=instance.roots?.[0];
  if(bound===current&&current.dataset.rv2Mounted)return;
  try{instance.rv2Cleanup?.();instance.rv2DestinationCleanup?.();clearInterval(instance.rv2Timer)}catch(_){}
  if(bound)delete bound.dataset.rv2Mounted;
  instance.roots=[current];
  delete current.dataset.rv2Mounted;
  mount(instance);
}
function installRestaurantRecovery(instance){
  if(instance.rv2RecoveryInstalled)return;
  instance.rv2RecoveryInstalled=true;
  const recover=()=>{if(document.hidden)return;requestAnimationFrame(()=>ensureRestaurantInteractivity(instance))};
  instance.rv2Recover=recover;
  document.addEventListener('visibilitychange',recover);
  window.addEventListener('focus',recover);
  window.addEventListener('pageshow',recover);
  window.addEventListener('luvia:screen-changed',recover);
}
function unmount(instance){instance.rv2Cleanup?.();instance.rv2DestinationCleanup?.();clearInterval(instance.rv2Timer);if(instance.rv2Recover){document.removeEventListener('visibilitychange',instance.rv2Recover);window.removeEventListener('focus',instance.rv2Recover);window.removeEventListener('pageshow',instance.rv2Recover);window.removeEventListener('luvia:screen-changed',instance.rv2Recover)}delete instance.rv2Cleanup;delete instance.rv2DestinationCleanup;delete instance.rv2Timer;delete instance.rv2Recover;delete instance.rv2RecoveryInstalled;if(instance.roots[0])delete instance.roots[0].dataset.rv2Mounted}
window.LuviaRestaurantMatch=Object.freeze({calculate:calculateMatchScore,normalize:normalizeMatchScore,get:matchScore});
async function openPlaceFromExternal(payload={}){
 const instance=window.LuviaModules?.instances?.get(MODULE_ID);if(!instance)return false;
 const candidates=[payload.tripPlaceId,payload.placeId,payload.providerPlaceId].filter(Boolean).map(String);
 const findEntry=model=>(model?.entries||[]).find(item=>candidates.includes(String(item.id||''))||candidates.includes(String(item.tripPlaceId||''))||candidates.includes(String(item.placeId||''))||candidates.includes(String(item.providerPlaceId||'')))||(payload.title?(model?.entries||[]).find(item=>String(item.name||'').trim().toLowerCase()===String(payload.title).trim().toLowerCase()):null);
 let entry=findEntry(instance.model);
 if((payload.mode==='schedule'||payload.tripPlaceId)&&(!entry||!entry.tripPlaceId)){
   const fresh=await modelFor(instance.trip);instance.model=fresh;entry=findEntry(fresh);
 }
 if(entry){
   const generic=/^(restaurant|unbenannter ort|unbekannter ort)$/i.test(String(entry.name||'').trim());
   if(generic&&payload.title&&!/^(restaurant|unbenannter ort|unbekannter ort)$/i.test(payload.title))entry={...entry,name:payload.title};
   const providerId=String(entry.providerPlaceId||entry.rawEntity?.place?.provider_place_id||payload.providerPlaceId||'').replace(/^places\//,'');
   if(payload.mode!=='schedule'&&(payload.overlayOnly||payload.returnView==='timeline'||providerId)){if(providerId){if(!instance.rv2SearchPlaces)instance.rv2SearchPlaces=new Map();instance.rv2SearchPlaces.set(providerId,{...entry,id:providerId,providerPlaceId:providerId,primaryType:'restaurant',_cardPhotoUri:entry._cardPhotoUri||entry.photoUri});await openRestaurantDetail(instance,providerId,{returnView:payload.returnView});return true;}}
   openRestaurantWorkspace(instance,entry,{returnView:payload.returnView,focusPlanning:payload.mode==='schedule'});return true;
 }
 if(payload.mode==='schedule'){
   try{const tripId=instance.trip?.tripId;const response=await window.LuviaPlaceEntities?.list?.({tripId,type:'restaurant'});let entries=(response?.data?.entities||[]).map(x=>window.LuviaRestaurants.entityToEntry(x));entry=findEntry({entries})||(payload.title?entries.find(item=>String(item.name||'').trim().toLowerCase()===String(payload.title).trim().toLowerCase()):null);let providerId=payload.providerPlaceId||'';if(!providerId&&payload.placeId){const known=window.LuviaPlaceCore?.getPlace?.(payload.placeId);providerId=known?.sourceId||known?.providerPlaceId||known?.metadata?.providerPlaceId||''}if(!entry&&!providerId&&payload.title&&window.LuviaRestaurants?.search){const found=await window.LuviaRestaurants.search(payload.title,{tripId,maxResultCount:5,persistRecommendations:false});const exact=(found?.data?.places||[]).find(place=>String(place.name||'').trim().toLowerCase()===String(payload.title).trim().toLowerCase())||(found?.data?.places||[])[0];providerId=String(exact?.id||exact?.providerPlaceId||'').replace(/^places\//,'')}if(!entry&&providerId&&window.LuviaRestaurants?.importPlace){const imported=await window.LuviaRestaurants.importPlace(providerId,{tripId,tripPlace:{status:'planned',plannedDate:payload.date,plannedTime:payload.time},restaurant:{reservationStatus:'idea'}});const entity=imported?.data?.entity||imported?.data;entry=entity?.tripPlace?window.LuviaRestaurants.entityToEntry(entity):null}if(!entry&&window.LuviaRestaurants?.list){const refreshed=await window.LuviaPlaceEntities.list({tripId,type:'restaurant'});entries=(refreshed?.data?.entities||[]).map(x=>window.LuviaRestaurants.entityToEntry(x));entry=findEntry({entries})||(payload.title?entries.find(item=>String(item.name||'').trim().toLowerCase()===String(payload.title).trim().toLowerCase()):null)}if(entry){const planned={...entry,name:payload.title||entry.name,tripId,date:payload.date||entry.date,time:payload.time||entry.time,plannedDate:payload.date||entry.date,plannedTime:payload.time||entry.time,lifecycleStatus:'planned'};window.LuviaScheduleIntelligence?.upsertRestaurant?.(planned);openRestaurantWorkspace(instance,planned,{returnView:payload.returnView,focusPlanning:true});return true}}catch(error){console.warn('[Luvia Restaurants] Planung konnte nicht nachgeladen oder importiert werden.',error)}window.LuviaUIKit?.toast?.('Die bestehende Tagesplanung konnte nicht eindeutig geladen werden.',{type:'error'});return false;}
 const providerId=payload.providerPlaceId||payload.placeId;if(providerId){if(!instance.rv2SearchPlaces)instance.rv2SearchPlaces=new Map();if(payload.title&&!instance.rv2SearchPlaces.has(providerId))instance.rv2SearchPlaces.set(providerId,{id:providerId,providerPlaceId:providerId,name:payload.title,primaryType:'restaurant'});await openRestaurantDetail(instance,providerId,{returnView:payload.returnView});return true;}return false;
}
